            let pref_val = src.fptn_preferred_server.trim();

            if !src.fptn_access_token.trim().is_empty() {
                out.extend(expand_fptn_token_outbounds(
                    &format!("fptn-{}", src.id),
                    &src.fptn_access_token,
                    sni_val,
                    bypass_val,
                    pref_val,
                ));
            }
