    #[test]
    fn test_bypass_section_ordered_before_disable_quic_and_isolate_p2p() {
        let mut store = RouterStoreData::default();
        store.settings.disable_quic = true;
        store.settings.isolate_p2p = true;
        store.outbound_sources.push(crate::store::OutboundSource {
            id: "src_dummy".to_string(),
            enabled: true,
            name: "Dummy".to_string(),
            source_type: "subscription".to_string(),
            cached_nodes: vec![crate::store::ParsedProxyNode {
                tag: "DummyNode".to_string(),
                protocol: "vless".to_string(),
                server: "198.51.100.30".to_string(),
                server_port: 443,
                outbound_json: json!({
                    "type": "vless",
                    "tag": "DummyNode",
                    "server": "198.51.100.30",
                    "server_port": 443,
                    "uuid": "33333333-3333-3333-3333-333333333333"
                }),
                ..Default::default()
            }],
            ..Default::default()
        });
        store.sections.clear();
        store.sections.push(RoutingSection {
            id: "ByPass".to_string(),
            enabled: true,
            label: "ByPass".to_string(),
            action: "direct".to_string(),
            user_domains: vec!["yandex.ru".to_string()],
            ..Default::default()
        });
        store.sections.push(RoutingSection {
            id: "Main".to_string(),
            enabled: true,
            label: "Main".to_string(),
            action: "proxy".to_string(),
            outbound_source_refs: vec!["src_dummy".to_string()],
            user_domains: vec!["example.com".to_string()],
            ..Default::default()
        });

        let cfg = compile_core_config(&store).expect("compile ByPass ordering");
        let rules = cfg["route"]["rules"].as_array().unwrap();
        let bypass_pos = rules
            .iter()
            .position(|r| r["domain_suffix"] == json!(["yandex.ru"]) && r["outbound"] == "direct")
            .expect("ByPass rule present");
        let p2p_pos = rules
            .iter()
            .position(|r| r["protocol"] == json!(["bittorrent"]) && r["outbound"] == "direct")
            .expect("isolate_p2p rule present");
        let quic_pos = rules
            .iter()
            .position(|r| {
                r["network"] == "udp" && r["port"] == json!([443]) && r["outbound"] == "block"
            })
            .expect("disable_quic rule present");
        let main_pos = rules
            .iter()
            .position(|r| r["domain_suffix"] == json!(["example.com"]))
            .expect("Main rule present");

        assert!(bypass_pos < p2p_pos);
        assert!(p2p_pos < quic_pos);
        assert!(quic_pos < main_pos);
    }

    #[test]
    fn test_or_condition_rules_discord_voice_resolve_and_inverted_composite() {
        let mut store = RouterStoreData::default();
        store.settings.enable_ipv6 = true;
        store.conditions.push(TrafficCondition {
            id: "cond_dc".to_string(),
            enabled: true,
            name: "Discord".to_string(),
            condition_type: "atomic".to_string(),
            community_lists: vec!["telegram".to_string(), "discord".to_string()],
            community_subnets: true,
            user_domains: vec!["example.org".to_string()],
            user_subnets: vec!["10.20.0.0/16".to_string()],
            client_ips: vec!["192.168.1.0/24".to_string()],
            ..Default::default()
        });
        store.conditions.push(TrafficCondition {
            id: "cond_inv".to_string(),
            enabled: true,
            invert: true,
            condition_type: "atomic".to_string(),
            user_domains: vec!["local.test".to_string()],
            user_subnets: vec!["10.99.0.0/16".to_string()],
            client_ips: vec!["192.168.1.50/32".to_string()],
            ..Default::default()
        });
        store.sections.clear();
        store.sections.push(RoutingSection {
            id: "discord_desync".to_string(),
            enabled: true,
            label: "Discord Desync".to_string(),
            action: "desync".to_string(),
            connection_type: "desync".to_string(),
            desync_mode: "fake".to_string(),
            condition_refs: vec!["cond_dc".to_string(), "cond_inv".to_string()],
            ..Default::default()
        });

        let cfg = compile_core_config(&store).expect("compile discord desync");
        let outbounds = cfg["outbounds"].as_array().unwrap();
        let dc_ob = outbounds
            .iter()
            .find(|o| o["tag"] == "desync-sec-discord_desync")
            .expect("desync outbound present");
        assert_eq!(dc_ob["udp_fake"], json!(true));

        let rules = cfg["route"]["rules"].as_array().unwrap();
        let rs_resolve_idx = rules
            .iter()
            .position(|r| {
                r["action"] == "resolve"
                    && r["server"] == "dns-remote"
                    && r["rule_set"] == json!(["trs-telegram", "trs-discord"])
                    && r["source_ip_cidr"] == json!(["192.168.1.0/24"])
            })
            .expect("resolve rule before rule_set");
        let rs_route_idx = rules
            .iter()
            .position(|r| {
                r["rule_set"] == json!(["trs-telegram", "trs-discord"])
                    && r["outbound"] == "desync-sec-discord_desync"
                    && r["source_ip_cidr"] == json!(["192.168.1.0/24"])
            })
            .expect("separate rule_set branch");
        assert!(rs_resolve_idx < rs_route_idx);

        assert!(rules.iter().any(|r| {
            r["domain_suffix"] == json!(["example.org"])
                && r["outbound"] == "desync-sec-discord_desync"
                && r.get("ip_cidr").is_none()
        }));
        let ip_rule = rules
            .iter()
            .find(|r| {
                r["outbound"] == "desync-sec-discord_desync"
                    && r.get("ip_cidr").is_some()
                    && r.get("port_range").is_none()
            })
            .expect("separate ip_cidr branch");
        let cidrs = ip_rule["ip_cidr"].as_array().unwrap();
        assert!(cidrs.contains(&json!("10.20.0.0/16")));
        assert!(cidrs.contains(&json!("149.154.160.0/20")));
        assert!(cidrs.contains(&json!("162.159.128.0/20")));

        assert!(rules.iter().any(|r| {
            r["network"] == "udp"
                && r["port_range"] == json!(DISCORD_VOICE_PORT_RANGES)
                && r["outbound"] == "desync-sec-discord_desync"
        }));
        assert!(rules.iter().any(|r| {
            r["network"] == "tcp"
                && r["port_range"] == json!(DISCORD_MEDIA_PORT_RANGES)
                && r["outbound"] == "desync-sec-discord_desync"
        }));

        let inv_rule = rules
            .iter()
            .find(|r| r["type"] == "logical" && r["mode"] == "and")
            .expect("multi-branch inverted rule wraps OR inside outer AND");
        let inner = inv_rule["rules"].as_array().unwrap();
        assert_eq!(inner[0]["source_ip_cidr"], json!(["192.168.1.50/32"]));
        assert_eq!(inner[1]["type"], "logical");
        assert_eq!(inner[1]["mode"], "or");
        assert_eq!(inner[1]["invert"], json!(true));
    }

    #[test]
    fn test_resolve_device_targets_with_arp_and_dhcp_tables() {
        let arp = "IP address       HW type     Flags       HW address            Mask     Device\n\
                   192.168.1.205    0x1         0x2         3e:83:67:22:fe:65     *        br-lan\n";
        let leases = "1700000000 aa:bb:cc:dd:ee:02 192.168.1.206 phone *\n";
        let resolved = resolve_device_targets_with_tables(
            &[
                "3E:83:67:22:FE:65".to_string(),
                "aa:bb:cc:dd:ee:02".to_string(),
                "192.168.1.50".to_string(),
                "ff:ff:ff:ff:ff:ff".to_string(),
            ],
            arp,
            leases,
        );
        assert_eq!(
            resolved,
            vec!["192.168.1.205/32", "192.168.1.206/32", "192.168.1.50/32"]
        );
    }

    #[test]
    fn test_tailscale_endpoints_magicdns_routes_and_xray_clamp() {
        let mut store = RouterStoreData::default();
        store.settings.fakeip_enabled = true;
        store.settings.enable_ipv6 = true;
        store.outbound_sources.push(crate::store::OutboundSource {
            id: "ts1".to_string(),
            enabled: true,
            source_type: "tailscale".to_string(),
            tailscale_mode: "singbox".to_string(),
            tailscale_ephemeral: true,
            tailscale_relay_server_port: "41641".to_string(),
            tailscale_accept_dns: true,
            tailscale_accept_default_resolvers: true,
            ..Default::default()
        });
        store.servers.push(crate::store::InboundServer {
            id: "srv_nat".to_string(),
            enabled: true,
            protocol: "tailscale".to_string(),
            tailscale_mode: "native".to_string(),
            ..Default::default()
        });

        let cfg = compile_core_config(&store).expect("compile core config with tailscale");
        let eps = cfg["endpoints"]
            .as_array()
            .expect("endpoints array must exist");
        assert_eq!(eps.len(), 1, "native server must not emit an endpoint");
        let ts_ep = &eps[0];
        assert_eq!(ts_ep["type"], "tailscale");
        assert_eq!(ts_ep["ephemeral"], json!(true));
        let state_dir = ts_ep["state_directory"]
            .as_str()
            .expect("state_directory string");
        assert!(state_dir.starts_with("/var/run/tachyon/tailscale/"));
        assert!(ts_ep.get("auth_key").is_none());
        assert_eq!(ts_ep["relay_server_port"], json!(41641));
        assert!(ts_ep.get("accept_dns").is_none());
        assert!(ts_ep.get("accept_default_resolvers").is_none());

        let dns_servers = cfg["dns"]["servers"].as_array().expect("dns servers array");
        assert!(dns_servers.iter().any(|s| s["type"] == "tailscale"));

        let dns_rules = cfg["dns"]["rules"].as_array().expect("dns rules array");
        let ts_rule_pos = dns_rules
            .iter()
            .position(|r| {
                r["domain_suffix"]
                    .as_array()
                    .is_some_and(|arr| arr.iter().any(|d| d == "ts.net"))
            })
            .expect("MagicDNS ts.net rule must exist");
        let fakeip_rule_pos = dns_rules
            .iter()
            .position(|r| r["server"] == "dns-fakeip")
            .expect("FakeIP fallback rule must exist");
        assert!(ts_rule_pos < fakeip_rule_pos);

        let route_rules = cfg["route"]["rules"].as_array().expect("route rules array");
        assert!(route_rules.iter().any(|r| {
            r["ip_cidr"].as_array().is_some_and(|arr| {
                arr.iter().any(|c| c == "100.64.0.0/10")
                    && arr.iter().any(|c| c == "fd7a:115c:a1e0::/48")
            })
        }));

        assert_eq!(xray_clamp_probe_interval("5s"), "30s");
        assert_eq!(xray_clamp_probe_interval("10s"), "30s");
        assert_eq!(xray_clamp_probe_interval("45s"), "45s");
    }

    #[test]
    fn test_mieru_simple_share_links_and_roundtrip() {
        let sample_uri = "mierus://testuser:testpass@198.51.100.10?profile=%F0%9F%87%AB%F0%9F%87%AE+Finland%7CLainDEV&mtu=1400&port=20100&protocol=TCP#%F0%9F%87%AB%F0%9F%87%AE%20Finland%7CLainDEV";
        let node1 = parse_proxy_uri(sample_uri, 0).expect("sample mierus:// must parse");
        assert_eq!(node1.protocol, "mieru");
        assert_eq!(node1.server, "198.51.100.10");
        assert_eq!(node1.server_port, 20100);
        assert_eq!(node1.tag, "\u{1F1EB}\u{1F1EE} Finland|LainDEV");
        assert_eq!(node1.outbound_json["transport"], "TCP");
        assert_eq!(node1.outbound_json["username"], "testuser");
        assert_eq!(node1.outbound_json["password"], "testpass");
        assert!(
            node1.outbound_json.get("mtu").is_none(),
            "mieru outbound must not emit unknown mtu field"
        );

        let link1 = serialize_mieru_outbound(&node1.outbound_json).expect("serialize sample mieru");
        assert!(link1.starts_with("mierus://testuser:testpass@198.51.100.10?"));
        assert!(!link1.contains(":443"));
        assert!(link1.contains("port=20100"));
        assert!(link1.contains("protocol=TCP"));
        assert!(link1.contains("profile="));
        let roundtrip1 = parse_proxy_uri(&link1, 1).expect("round-trip mierus:// must parse");
        assert_eq!(roundtrip1.server_port, 20100);
        assert_eq!(roundtrip1.tag, "\u{1F1EB}\u{1F1EE} Finland|LainDEV");

        let encoded_uri = "mierus://user%3Aone:p%3Ass@203.0.113.5?port=20200&protocol=UDP#EncCreds";
        let enc_node = parse_proxy_uri(encoded_uri, 2).expect("encoded credentials mierus://");
        assert_eq!(enc_node.outbound_json["username"], "user:one");
        assert_eq!(enc_node.outbound_json["password"], "p:ss");
        assert_eq!(enc_node.server_port, 20200);
        assert_eq!(enc_node.outbound_json["transport"], "UDP");

        let range_uri = "mierus://u:p@203.0.113.6?port=2010-2020&protocol=UDP#RangeBug";
        let range_node = parse_proxy_uri(range_uri, 3).expect("range mierus://");
        assert!(range_node.outbound_json.get("server_port").is_none());
        assert_eq!(
            range_node.outbound_json["server_ports"],
            json!(["2010-2020"])
        );
        assert_eq!(range_node.server_port, 2010);
        let range_link =
            serialize_mieru_outbound(&range_node.outbound_json).expect("serialize range mieru");
        assert!(range_link.starts_with("mierus://u:p@203.0.113.6?"));
        assert!(range_link.contains("port=2010-2020"));

        let multi_uri = "mierus://u:p@203.0.113.7?port=2010&port=2020-2030&protocol=TCP&traffic-pattern=random#MultiPort";
        let multi_node = parse_proxy_uri(multi_uri, 4).expect("multi-port mierus://");
        assert!(multi_node.outbound_json.get("server_port").is_none());
        assert_eq!(
            multi_node.outbound_json["server_ports"],
            json!(["2010", "2020-2030"])
        );
        assert_eq!(multi_node.outbound_json["traffic_pattern"], "random");
        let multi_link =
            serialize_mieru_outbound(&multi_node.outbound_json).expect("serialize multi mieru");
        assert!(multi_link.contains("port=2010&port=2020-2030"));
        assert!(multi_link.contains("traffic-pattern=random"));

        let ipv6_uri = "mierus://u:p@[2001:db8::1]?port=20443&protocol=UDP#V6Node";
        let v6_node = parse_proxy_uri(ipv6_uri, 5).expect("IPv6 mierus://");
        assert_eq!(v6_node.server, "2001:db8::1");
        assert_eq!(v6_node.server_port, 20443);
        let v6_link = serialize_mieru_outbound(&v6_node.outbound_json).expect("serialize v6 mieru");
        assert!(v6_link.starts_with("mierus://u:p@[2001:db8::1]?"));
        assert!(v6_link.contains("port=20443"));

        let query_profile_uri =
            "mierus://u:p@203.0.113.8?profile=FromQuery&port=20500&protocol=TCP";
        let qp_node = parse_proxy_uri(query_profile_uri, 6).expect("query profile mierus://");
        assert_eq!(qp_node.tag, "FromQuery");

        assert!(parse_proxy_uri("mierus://u:p@203.0.113.10", 7).is_none());
        assert!(parse_proxy_uri("mierus://203.0.113.10?port=20100", 8).is_none());
        assert!(parse_proxy_uri("mierus://u:p@203.0.113.10?port=20200-20100", 9).is_none());
        assert!(parse_proxy_uri("mierus://u:p@203.0.113.10?port=70000", 10).is_none());

        let srv = crate::store::InboundServer {
            id: "srv_m".to_string(),
            enabled: true,
            label: "Node1".to_string(),
            protocol: "mieru".to_string(),
            listen_port: 20500,
            server_username: "u".to_string(),
            password: "p".to_string(),
            mieru_transport: "UDP".to_string(),
            ..Default::default()
        };
        let srv_uri = build_server_share_uri(&srv, Some("203.0.113.50"));
        assert!(srv_uri.starts_with("mierus://u:p@203.0.113.50?"));
        assert!(!srv_uri.contains("203.0.113.50:20500"));
        assert!(srv_uri.contains("port=20500"));
        assert!(srv_uri.contains("protocol=UDP"));

        let mut store = RouterStoreData::default();
        store.outbound_sources.push(crate::store::OutboundSource {
            id: "m1".to_string(),
            enabled: true,
            source_type: "mieru".to_string(),
            server: "203.0.113.9".to_string(),
            server_ports: vec!["20100-20110".to_string()],
            username: "u".to_string(),
            password: "p".to_string(),
            mieru_transport: "UDP".to_string(),
            mieru_multiplexing: "MULTIPLEXING_HIGH".to_string(),
            ..Default::default()
        });
        let cfg = compile_core_config(&store).expect("compile mieru source outbound");
        let ob = cfg["outbounds"]
            .as_array()
            .and_then(|arr| arr.iter().find(|o| o["type"] == "mieru"))
            .expect("mieru outbound must exist");
        assert_eq!(ob["transport"], "UDP");
        assert_eq!(ob["server_ports"], json!(["20100-20110"]));
        assert_eq!(ob["multiplexing"], "MULTIPLEXING_HIGH");
        assert!(ob.get("server_port").is_none());
    }

    #[test]
    fn test_incomplete_sources_skipped_without_invalid_outbounds() {
        let empty_mieru = OutboundSource {
            id: "MeiruTest".to_string(),
            enabled: true,
            source_type: "mieru".to_string(),
            ..Default::default()
        };
        assert!(build_source_outbounds(&empty_mieru).is_empty());

        let mieru_no_ports = OutboundSource {
            id: "MeiruNoPort".to_string(),
            enabled: true,
            source_type: "mieru".to_string(),
            server: "203.0.113.10".to_string(),
            ..Default::default()
        };
        assert!(build_source_outbounds(&mieru_no_ports).is_empty());

        let valid_mieru = OutboundSource {
            id: "MeiruOk".to_string(),
            enabled: true,
            source_type: "mieru".to_string(),
            server: " 203.0.113.10 ".to_string(),
            server_port: 8443,
            ..Default::default()
        };
        let mieru_out = build_source_outbounds(&valid_mieru);
        assert_eq!(mieru_out.len(), 1);
        assert_eq!(mieru_out[0].1["server"], "203.0.113.10");
        assert_eq!(mieru_out[0].1["server_port"], 8443);

        for st in ["anytls", "naive", "snell"] {
            let empty_srv = OutboundSource {
                id: format!("empty_{st}"),
                enabled: true,
                source_type: st.to_string(),
                server: "   ".to_string(),
                ..Default::default()
            };
            assert!(
                build_source_outbounds(&empty_srv).is_empty(),
                "expected empty outbounds for {st} without server"
            );
        }

        let tor_src = OutboundSource {
            id: "tor1".to_string(),
            enabled: true,
            source_type: "tor".to_string(),
            ..Default::default()
        };
        assert_eq!(build_source_outbounds(&tor_src).len(), 1);

        let empty_fptn = OutboundSource {
            id: "fptn_empty".to_string(),
            enabled: true,
            source_type: "fptn".to_string(),
            ..Default::default()
        };
        assert!(build_source_outbounds(&empty_fptn).is_empty());

        let empty_iface = OutboundSource {
            id: "iface_empty".to_string(),
            enabled: true,
            source_type: "interface".to_string(),
            interface_name: "   ".to_string(),
            ..Default::default()
        };
        assert!(build_source_outbounds(&empty_iface).is_empty());

        let empty_wg = OutboundSource {
            id: "wg_empty".to_string(),
            enabled: true,
            source_type: "wireguard".to_string(),
            ..Default::default()
        };
        assert!(build_source_outbounds(&empty_wg).is_empty());
    }

    #[test]
    fn test_ipv6_share_uri_wg_conf_and_host_port_extraction() {
        assert_eq!(extract_host_only("[2001:db8::1]:443"), "2001:db8::1");
        assert_eq!(extract_host_only("[2001:db8::1]"), "2001:db8::1");
        assert_eq!(extract_host_only("2001:db8::1"), "2001:db8::1");
        assert_eq!(extract_host_only("vpn.example.com:8443"), "vpn.example.com");

        for proto in [
            "vless",
            "trojan",
            "hysteria2",
            "tuic",
            "shadowsocks",
            "tewfai",
        ] {
            let srv = crate::store::InboundServer {
                id: format!("srv_{proto}"),
                enabled: true,
                label: "V6Node".to_string(),
                protocol: proto.to_string(),
                listen_port: 8443,
                server_uuid: "11111111-1111-1111-1111-111111111111".to_string(),
                password: "secret".to_string(),
                method: "2022-blake3-aes-128-gcm".to_string(),
                ..Default::default()
            };
            for raw_host in ["[2001:db8::1]:443", "[2001:db8::1]", "2001:db8::1"] {
                let uri = build_server_share_uri(&srv, Some(raw_host));
                assert!(
                    uri.contains("@[2001:db8::1]:8443"),
                    "{proto} with {raw_host} produced invalid URI: {uri}"
                );
                assert!(!uri.contains("[["));
                assert!(!uri.contains("sni=["));
                if proto != "shadowsocks" {
                    assert!(
                        uri.contains("sni=2001:db8::1"),
                        "{proto} fallback sni must be unbracketed: {uri}"
                    );
                }
            }
        }

        // ShadowTLS with empty handshake server falls back to unbracketed SNI
        let stls_srv = crate::store::InboundServer {
            id: "srv_stls".to_string(),
            enabled: true,
            label: "V6STLS".to_string(),
            protocol: "shadowtls".to_string(),
            listen_port: 443,
            password: "secret".to_string(),
            ..Default::default()
        };
        let stls_uri = build_server_share_uri(&stls_srv, Some("[2001:db8::1]:443"));
        assert!(stls_uri.contains("@[2001:db8::1]:443"), "stls={stls_uri}");
        assert!(stls_uri.contains("sni=2001:db8::1"), "stls={stls_uri}");
        assert!(!stls_uri.contains("sni=["), "stls={stls_uri}");

        // VMess stores unbracketed host inside base64 JSON "add" field
        let vmess_srv = crate::store::InboundServer {
            id: "srv_vmess".to_string(),
            enabled: true,
            label: "V6VMess".to_string(),
            protocol: "vmess".to_string(),
            listen_port: 443,
            server_uuid: "11111111-1111-1111-1111-111111111111".to_string(),
            ..Default::default()
        };
        let vmess_uri = build_server_share_uri(&vmess_srv, Some("[2001:db8::2]:8443"));
        let b64 = vmess_uri.strip_prefix("vmess://").expect("vmess scheme");
        let decoded = base64::engine::general_purpose::STANDARD
            .decode(b64)
            .expect("valid vmess base64");
        let vmess_json: Value = serde_json::from_slice(&decoded).expect("vmess json");
        assert_eq!(vmess_json["add"], "2001:db8::2");
        assert_eq!(vmess_json["sni"], "2001:db8::2");
        assert_eq!(vmess_json["host"], "2001:db8::2");
        assert_eq!(vmess_json["port"], "443");

        // MTProto keeps bare IPv6 in tg://proxy?server=...
        let mt_srv = crate::store::InboundServer {
            id: "srv_mt".to_string(),
            enabled: true,
            label: "V6MT".to_string(),
            protocol: "mtproto".to_string(),
            listen_port: 443,
            mtproto_secret: "dd000102030405060708090a0b0c0d0e0f".to_string(),
            ..Default::default()
        };
        let mt_uri = build_server_share_uri(&mt_srv, Some("[2001:db8::3]:443"));
        assert!(
            mt_uri.contains("server=2001:db8::3&port=443"),
            "mt={mt_uri}"
        );

        // WireGuard / AWG client config puts [ipv6]:port in Endpoint
        let wg_srv = crate::store::InboundServer {
            id: "srv_wg".to_string(),
            enabled: true,
            label: "V6WG".to_string(),
            protocol: "wireguard".to_string(),
            listen_port: 51820,
            awg_server_public_key: "PUBKEY".to_string(),
            ..Default::default()
        };
        let wg_conf = build_server_wg_conf(&wg_srv, Some("[2001:db8::4]:443"));
        assert!(
            wg_conf.contains("Endpoint = [2001:db8::4]:51820"),
            "wg_conf={wg_conf}"
        );
    }

    #[test]
    fn test_fakeip_disabled_and_ipv6_aaaa_noerror_and_dns_strategy_clamp() {
        let mut store = RouterStoreData::default();
        store.settings.ipv6_mode = "off".to_string();
        store.settings.ipv6_leak_guard = true;
        store.settings.dns_strategy = "prefer_ipv6".to_string();
        store.settings.fakeip_enabled = false;
        store.settings.cache_path = "/usr/share/tachyon-core/cache.db".to_string();

        let cfg_v4_nofake =
            compile_core_config_with_wan6(&store, true).expect("compile ipv6 off no fakeip");
        assert_eq!(cfg_v4_nofake["dns"]["strategy"], "ipv4_only");
        assert!(
            !cfg_v4_nofake["dns"]["servers"]
                .as_array()
                .unwrap()
                .iter()
                .any(|s| s["tag"] == "dns-fakeip")
        );
        assert!(
            !cfg_v4_nofake["experimental"]["cache_file"]["store_fakeip"]
                .as_bool()
                .unwrap_or(false)
        );
        assert_eq!(
            cfg_v4_nofake["experimental"]["cache_file"]["path"],
            "/tmp/tachyon-core/cache.db"
        );
        let dns_rules = cfg_v4_nofake["dns"]["rules"].as_array().unwrap();
        assert!(dns_rules.iter().any(|r| {
            r["action"] == "predefined"
                && r["query_type"] == json!(["AAAA"])
                && r["rcode"] == "NOERROR"
        }));
        assert!(
            !dns_rules
                .iter()
                .any(|r| r["action"] == "reject" && r["query_type"] == json!(["AAAA"]))
        );

        // Enable dual_stack + fakeip: both IPv4 & IPv6 FakeIP ranges + prefer_ipv6 honored
        store.settings.ipv6_mode = "dual_stack".to_string();
        store.settings.fakeip_enabled = true;
        store.settings.fakeip_inet4_range = "198.18.0.0/15".to_string();
        store.settings.fakeip_inet6_range = "fc00::/18".to_string();
        store.settings.tun_inet4 = "172.19.0.1/30".to_string();
        store.settings.tun_inet6 = "fdfe:dcba:9876::1/126".to_string();
        store.settings.proxy_mode = "tun".to_string();

        let cfg_dual =
            compile_core_config_with_wan6(&store, true).expect("compile dual stack fakeip");
        assert_eq!(cfg_dual["dns"]["strategy"], "prefer_ipv6");
        let fakeip_srv = cfg_dual["dns"]["servers"]
            .as_array()
            .unwrap()
            .iter()
            .find(|s| s["tag"] == "dns-fakeip")
            .expect("dns-fakeip server present");
        assert_eq!(fakeip_srv["inet4_range"], "198.18.0.0/15");
        assert_eq!(fakeip_srv["inet6_range"], "fc00::/18");
        assert_eq!(
            cfg_dual["experimental"]["cache_file"]["store_fakeip"],
            json!(true)
        );
        let tun_ib = cfg_dual["inbounds"]
            .as_array()
            .unwrap()
            .iter()
            .find(|i| i["type"] == "tun")
            .expect("tun inbound present");
        assert_eq!(
            tun_ib["address"],
            json!(["172.19.0.1/30", "fdfe:dcba:9876::1/126"])
        );
    }

    #[test]
    fn test_m1_compact_vpn_uri_and_inflate_zlib_bounded() {
        assert_eq!(
            compact_vpn_uri("  vpn://AA BB\n\tCC\r\n DD #my node  "),
            "vpn://AABBCCDD#my node"
        );
        assert_eq!(compact_vpn_uri("vpn://AA BB\nCC"), "vpn://AABBCC");

        // 1. Stored DEFLATE block (BTYPE=00)
        let b0_zlib: &[u8] = &[
            0x78, 0x01, 0x01, 0x23, 0x00, 0xdc, 0xff, 0x73, 0x74, 0x6f, 0x72, 0x65, 0x64, 0x20,
            0x64, 0x65, 0x66, 0x6c, 0x61, 0x74, 0x65, 0x20, 0x70, 0x61, 0x79, 0x6c, 0x6f, 0x61,
            0x64, 0x20, 0x68, 0x65, 0x6c, 0x6c, 0x6f, 0x20, 0x77, 0x6f, 0x72, 0x6c, 0x64, 0x21,
            0xf2, 0x8c, 0x0d, 0x2e,
        ];
        assert_eq!(
            inflate_zlib_bounded(b0_zlib, AMNEZIA_VPN_MAX_PAYLOAD_BYTES).as_deref(),
            Some(b"stored deflate payload hello world!".as_slice())
        );

        // 2. Fixed Huffman (BTYPE=01) + Qt qCompress header + Qt 0x000000FF framing
        let b1_zlib: &[u8] = &[
            0x78, 0x01, 0xab, 0x56, 0xca, 0xc8, 0x2f, 0x2e, 0x51, 0xb2, 0x52, 0x4a, 0xad, 0x48,
            0xcc, 0x2d, 0xc8, 0x49, 0xd5, 0x4b, 0xce, 0xcf, 0x55, 0xd2, 0x51, 0x2a, 0xc8, 0x2f,
            0x2a, 0x51, 0xb2, 0x32, 0x31, 0x31, 0xd6, 0x51, 0x2a, 0x28, 0xca, 0x2f, 0xc9, 0x57,
            0xb2, 0x52, 0x4a, 0x2c, 0x4f, 0x57, 0xaa, 0x05, 0x00, 0x76, 0x8c, 0x0f, 0x3d,
        ];
        let b1_expected = br#"{"host":"example.com","port":443,"proto":"awg"}"#;
        assert_eq!(
            inflate_zlib_bounded(b1_zlib, AMNEZIA_VPN_MAX_PAYLOAD_BYTES).as_deref(),
            Some(b1_expected.as_slice())
        );

        let mut qt_framed = vec![0x00, 0x00, 0x00, b1_expected.len() as u8];
        qt_framed.extend_from_slice(b1_zlib);
        assert_eq!(
            inflate_zlib_bounded(&qt_framed, AMNEZIA_VPN_MAX_PAYLOAD_BYTES).as_deref(),
            Some(b1_expected.as_slice())
        );

        let mut ff_framed = vec![0x00, 0x00, 0x00, 0xff];
        ff_framed.extend_from_slice(b1_zlib);
        assert_eq!(
            inflate_zlib_bounded(&ff_framed, AMNEZIA_VPN_MAX_PAYLOAD_BYTES).as_deref(),
            Some(b1_expected.as_slice())
        );

        // 3. Dynamic Huffman (BTYPE=10) multi-KB container
        let b2_zlib = base64::engine::general_purpose::STANDARD
            .decode("")
            .expect("valid b2 zlib fixture");
        let b2_expected = base64::engine::general_purpose::STANDARD
            .decode("")
            .expect("valid b2 expected fixture");
        assert_eq!(
            inflate_zlib_bounded(&b2_zlib, AMNEZIA_VPN_MAX_PAYLOAD_BYTES).as_deref(),
            Some(b2_expected.as_slice())
        );

        // 4. Reject corrupt Adler-32, truncated stream, invalid distance back-ref, and zip bombs
        let corrupt_adler: &[u8] = &[
            0x78, 0x01, 0xab, 0x56, 0xca, 0xc8, 0x2f, 0x2e, 0x51, 0xb2, 0x52, 0x4a, 0xad, 0x48,
            0xcc, 0x2d, 0xc8, 0x49, 0xd5, 0x4b, 0xce, 0xcf, 0x55, 0xd2, 0x51, 0x2a, 0xc8, 0x2f,
            0x2a, 0x51, 0xb2, 0x32, 0x31, 0x31, 0xd6, 0x51, 0x2a, 0x28, 0xca, 0x2f, 0xc9, 0x57,
            0xb2, 0x52, 0x4a, 0x2c, 0x4f, 0x57, 0xaa, 0x05, 0x00, 0x76, 0x8c, 0x0f, 0xc2,
        ];
        assert!(inflate_zlib_bounded(corrupt_adler, AMNEZIA_VPN_MAX_PAYLOAD_BYTES).is_none());
        assert!(
            inflate_zlib_bounded(&b1_zlib[..b1_zlib.len() - 3], AMNEZIA_VPN_MAX_PAYLOAD_BYTES)
                .is_none()
        );
        let invalid_backref: &[u8] = &[0x78, 0x9c, 0x03, 0x02, 0x00, 0x00, 0x00, 0x00, 0x01];
        assert!(inflate_zlib_bounded(invalid_backref, AMNEZIA_VPN_MAX_PAYLOAD_BYTES).is_none());

        let zip_bomb: &[u8] = &[
            0x78, 0xda, 0xed, 0xc1, 0x31, 0x01, 0x00, 0x00, 0x00, 0xc2, 0xa0, 0x6c, 0xeb, 0x5f,
            0xca, 0x12, 0x9e, 0x40, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00,
            0x00, 0x00, 0x6f, 0x03, 0x3f, 0xee, 0x71, 0x7c,
        ];
        assert!(inflate_zlib_bounded(zip_bomb, AMNEZIA_VPN_MAX_PAYLOAD_BYTES).is_none());
        let ok_exact = inflate_zlib_bounded(zip_bomb, 70_000).expect("70000 fits exact bound");
        assert_eq!(ok_exact.len(), 70_000);
        assert!(ok_exact.iter().all(|&b| b == b'A'));
    }

