    #[test]
    fn test_bypass_section_before_match_all_proxy_domains_and_stale_outbound_refs() {
        // Reproduces user bug: a section switched to action=bypass (with stale connection_type=proxy
        // and stale outbound_source_refs / fail_policy=block) before a match_all proxy section.
        let mut store = make_bypass_before_match_all_store(true);
        store.sections = vec![
            RoutingSection {
                id: "sec_bypass".to_string(),
                enabled: true,
                label: "Direct Bypass".to_string(),
                action: "bypass".to_string(),
                connection_type: "proxy".to_string(),
                outbound_source_refs: vec!["src_proxy".to_string()],
                fail_policy: "block".to_string(),
                domains: vec!["bank.ru".to_string()],
                community_lists: vec!["russia_inside".to_string()],
                ..Default::default()
            },
            RoutingSection {
                id: "sec_all".to_string(),
                enabled: true,
                label: "All via Proxy".to_string(),
                action: "proxy".to_string(),
                connection_type: "proxy".to_string(),
                outbound_source_refs: vec!["src_proxy".to_string()],
                match_all: true,
                ..Default::default()
            },
        ];

        let cfg = compile_core_config_with_wan6(&store, false).expect("compile bypass+match_all");
        let route_rules = cfg["route"]["rules"].as_array().unwrap();
        let idx_bypass_dom = route_rules
            .iter()
            .position(|r| r["domain_suffix"] == json!(["bank.ru"]) && r["outbound"] == "direct")
            .expect("bypass domain rule must target direct, never ProxyNode");
        let idx_bypass_list = route_rules
            .iter()
            .position(|r| {
                r["rule_set"] == json!(["trs-russia_inside"]) && r["outbound"] == "direct"
            })
            .expect("bypass list rule must target direct");
        let idx_match_all = route_rules
            .iter()
            .position(|r| {
                r["outbound"] == "ProxyNode"
                    && r.get("domain_suffix").is_none()
                    && r.get("rule_set").is_none()
                    && r.get("inbound").is_none()
            })
            .expect("match_all proxy rule");
        assert!(idx_bypass_dom < idx_match_all);
        assert!(idx_bypass_list < idx_match_all);

        let dns_rules = cfg["dns"]["rules"].as_array().unwrap();
        let idx_dns_bypass = dns_rules
            .iter()
            .position(|r| r["server"] == "dns-remote" && r["domain_suffix"] == json!(["bank.ru"]))
            .expect("bypass domain must resolve via real DNS before fakeip");
        let idx_dns_fakeip = dns_rules
            .iter()
            .position(|r| r["server"] == "dns-fakeip")
            .expect("dns-fakeip rule");
        assert!(idx_dns_bypass < idx_dns_fakeip);
    }

    #[test]
    fn test_bypass_section_before_match_all_proxy_subnets_and_geoip_under_fakeip() {
        // Under FakeIP, IP/GeoIP bypass rules before match_all require an earlier `resolve` action
        // so FakeIP-backed Target::Domain connections populate destination_addresses and match bypass.
        let mut store = make_bypass_before_match_all_store(true);
        store.sections = vec![
            RoutingSection {
                id: "sec_bypass_ip".to_string(),
                enabled: true,
                label: "Bypass Subnets & RU".to_string(),
                action: "bypass".to_string(),
                connection_type: "bypass".to_string(),
                user_subnets: vec!["185.71.76.0/24".to_string()],
                geoip_codes: vec!["ru".to_string()],
                ..Default::default()
            },
            RoutingSection {
                id: "sec_all".to_string(),
                enabled: true,
                label: "All via Proxy".to_string(),
                action: "proxy".to_string(),
                connection_type: "proxy".to_string(),
                outbound_source_refs: vec!["src_proxy".to_string()],
                match_all: true,
                ..Default::default()
            },
        ];

        let cfg =
            compile_core_config_with_wan6(&store, false).expect("compile subnet+geoip bypass");
        let route_rules = cfg["route"]["rules"].as_array().unwrap();
        let idx_resolve = route_rules
            .iter()
            .position(|r| r["action"] == "resolve" && r["server"] == "dns-remote")
            .expect("FakeIP IP/GeoIP bypass must emit resolve rule before IP matchers");
        let idx_geoip = route_rules
            .iter()
            .position(|r| r["rule_set"] == json!(["geoip-ru"]) && r["outbound"] == "direct")
            .expect("geoip-ru direct rule");
        let idx_subnet = route_rules
            .iter()
            .position(|r| r["ip_cidr"] == json!(["185.71.76.0/24"]) && r["outbound"] == "direct")
            .expect("subnet direct rule");
        let idx_proxy = route_rules
            .iter()
            .position(|r| r["outbound"] == "ProxyNode" && r.get("inbound").is_none())
            .expect("match_all proxy rule");
        assert!(idx_resolve < idx_geoip);
        assert!(idx_resolve < idx_subnet);
        assert!(idx_geoip < idx_proxy);
        assert!(idx_subnet < idx_proxy);

        // When FakeIP is disabled, no extra resolve rule is needed for IP/GeoIP bypass
        store.settings.fakeip_enabled = false;
        let cfg_nofake = compile_core_config_with_wan6(&store, false).expect("compile no-fakeip");
        let rules_nofake = cfg_nofake["route"]["rules"].as_array().unwrap();
        assert!(!rules_nofake.iter().any(|r| r["action"] == "resolve"));
    }

    #[test]
    fn test_bypass_section_before_match_all_proxy_routed_dns_and_full_tunnel() {
        // When FakeIP is OFF (or ON) and match_all proxy has routed_dns_enabled=true,
        // an earlier bypass/direct section must still emit real-IP DNS rules BEFORE match_all's routed DNS,
        // and bypass device (fully_routed_ips) must not emit an unintended catch-all direct rule.
        let mut store = make_bypass_before_match_all_store(false);
        store.settings.routing_strategy = "full_tunnel".to_string();
        store.sections = vec![
            RoutingSection {
                id: "sec_bypass_dev".to_string(),
                enabled: true,
                label: "Bypass TV".to_string(),
                action: "direct".to_string(),
                connection_type: "direct".to_string(),
                fully_routed_ips: vec!["192.168.1.88".to_string()],
                ..Default::default()
            },
            RoutingSection {
                id: "sec_bypass_dom".to_string(),
                enabled: true,
                label: "Bypass RU".to_string(),
                action: "direct".to_string(),
                connection_type: "direct".to_string(),
                domains: vec!["gosuslugi.ru".to_string()],
                ..Default::default()
            },
            RoutingSection {
                id: "sec_all".to_string(),
                enabled: true,
                label: "Match All Proxy".to_string(),
                action: "proxy".to_string(),
                connection_type: "proxy".to_string(),
                outbound_source_refs: vec!["src_proxy".to_string()],
                match_all: true,
                routed_dns_enabled: true,
                routed_dns_type: "doh".to_string(),
                routed_dns_servers: vec!["https://1.1.1.1/dns-query".to_string()],
                ..Default::default()
            },
        ];

        let cfg = compile_core_config_with_wan6(&store, false)
            .expect("compile bypass + routed_dns match_all + full_tunnel");
        let route_rules = cfg["route"]["rules"].as_array().unwrap();

        // fully_routed_ips bypass section must NOT emit an unconditional catch-all direct rule
        assert!(
            !route_rules.iter().any(|r| {
                r.as_object()
                    .is_some_and(|m| m.len() == 1 && m.get("outbound") == Some(&json!("direct")))
            }),
            "fully_routed_ips bypass must not synthesize catch-all direct rule"
        );
        let idx_dev = route_rules
            .iter()
            .position(|r| {
                r["source_ip_cidr"] == json!(["192.168.1.88/32"]) && r["outbound"] == "direct"
            })
            .expect("device bypass rule");
        let idx_dom = route_rules
            .iter()
            .position(|r| {
                r["domain_suffix"] == json!(["gosuslugi.ru"]) && r["outbound"] == "direct"
            })
            .expect("domain bypass rule");
        let idx_match_all = route_rules
            .iter()
            .position(|r| r["outbound"] == "ProxyNode" && r.get("inbound").is_none())
            .expect("match_all proxy rule");
        let idx_full_tunnel = route_rules
            .iter()
            .position(|r| r["outbound"] == "ProxyNode" && r["inbound"] == json!(["tproxy-in"]))
            .expect("full_tunnel proxy rule");
        assert!(idx_dev < idx_match_all);
        assert!(idx_dom < idx_match_all);
        assert!(idx_match_all < idx_full_tunnel);

        // DNS: bypass domain must hit dns-remote BEFORE match_all's dns-routed-sec_all
        let dns_rules = cfg["dns"]["rules"].as_array().unwrap();
        let idx_dns_bypass = dns_rules
            .iter()
            .position(|r| {
                r["server"] == "dns-remote" && r["domain_suffix"] == json!(["gosuslugi.ru"])
            })
            .expect("direct section domain must emit BypassRealIp before match_all routed DNS");
        let idx_dns_match_all = dns_rules
            .iter()
            .position(|r| r["server"] == "dns-routed-sec_all" && r.get("domain_suffix").is_none())
            .expect("match_all routed DNS rule");
        assert!(idx_dns_bypass < idx_dns_match_all);
    }

    #[test]
    fn test_bootstrap_parallel_doh_and_sticky_pool_tolerance() {
        let mut store = RouterStoreData::default();
        store.settings.bootstrap_dns_servers = vec![
            "77.88.8.8".to_string(),
            "https://dns.google/dns-query".to_string(),
            "quic://dns.adguard-dns.com".to_string(),
        ];
        store.balancers.push(BalancerConfig {
            id: "bal_sticky_test".to_string(),
            name: "Sticky Test".to_string(),
            enabled: true,
            balancer_type: "urltest".to_string(),
            mode: "sticky".to_string(),
            sticky_hash: "source_ip".to_string(),
            tolerance: 150,
            ..Default::default()
        });
        store.outbound_sources.push(OutboundSource {
            id: "src_1".to_string(),
            enabled: true,
            source_type: "proxy_links".to_string(),
            proxy_links: vec![
                "ss://YWVzLTI1Ni1nY206dGVzdA==@node1.example.com:443#N1".to_string(),
                "ss://YWVzLTI1Ni1nY206dGVzdA==@node2.example.com:443#N2".to_string(),
            ],
            ..Default::default()
        });
        store.sections.push(RoutingSection {
            id: "sec_s".to_string(),
            enabled: true,
            label: "StickySec".to_string(),
            action: "connection".to_string(),
            connection_type: "proxy".to_string(),
            outbound_source_refs: vec!["src_1".to_string()],
            balancer_refs: vec!["bal_sticky_test".to_string()],
            match_all: true,
            ..Default::default()
        });

        let cfg = compile_core_config_with_wan6(&store, false).expect("compile cfg");
        let dns_srvs = cfg["dns"]["servers"].as_array().unwrap();
        let boot_grp = dns_srvs
            .iter()
            .find(|s| s["tag"] == "dns-bootstrap")
            .expect("dns-bootstrap group");
        assert_eq!(boot_grp["mode"], "parallel");
        let boot_doh = dns_srvs
            .iter()
            .find(|s| s["tag"] == "dns-bootstrap-2")
            .expect("dns-bootstrap-2 DoH");
        assert_eq!(boot_doh["type"], "https");
        assert_eq!(boot_doh["domain_resolver"], "dns-bootstrap-1");
        let boot_doq = dns_srvs
            .iter()
            .find(|s| s["tag"] == "dns-bootstrap-3")
            .expect("dns-bootstrap-3 DoQ");
        assert_eq!(boot_doq["type"], "quic");
        assert_eq!(boot_doq["domain_resolver"], "dns-bootstrap-1");

        let sticky_ob = cfg["outbounds"]
            .as_array()
            .unwrap()
            .iter()
            .find(|o| o["tag"] == "bal-sec_s-bal_sticky_test")
            .expect("sticky balancer outbound");
        assert_eq!(sticky_ob["balancer"]["pool_tolerance"], 500);
        assert!(sticky_ob["balancer"].get("pool").is_none());
    }

    #[test]
    fn test_dns_loop_aaaa_invert_and_configured_doh_upstream_regressions() {
        // 1. OpenWrt dnsmasq-server non-dns-in rule uses logical AND instead of flat invert+domain_suffix,
        //    and configured Yandex DoH upstream is bootstrapped and excluded from NXDOMAIN intercept rule.
        let mut store = RouterStoreData::default();
        store.settings.ipv6_mode = "off".to_string();
        store.settings.fakeip_enabled = true;
        store.settings.dns_intercept_all = true;
        store.settings.dns_type = "doh".to_string();
        store.settings.dns_servers =
            vec!["https://common.dot.dns.yandex.net/dns-query".to_string()];
        store.settings.bootstrap_dns_servers = vec!["77.88.8.8".to_string()];

        let cfg = compile_core_config_with_wan6(&store, false).expect("compile cfg");
        let dns_rules = cfg["dns"]["rules"].as_array().expect("dns.rules");
        assert!(
            !dns_rules.iter().any(|r| {
                r.get("type").is_none()
                    && r.get("invert").and_then(Value::as_bool) == Some(true)
                    && r.get("domain_suffix").is_some()
            }),
            "flat invert+domain_suffix rule causes external domain DNS loops"
        );
        assert!(
            dns_rules.iter().any(|r| {
                r["server"] == "dnsmasq-server"
                    && r["type"] == "logical"
                    && r["mode"] == "and"
                    && r["rules"][0] == json!({ "inbound": ["dns-in"], "invert": true })
            }),
            "logical AND dnsmasq-server rule missing"
        );
        assert!(
            dns_rules.iter().any(|r| {
                r["server"] == "dns-bootstrap"
                    && r["domain"]
                        .as_array()
                        .is_some_and(|a| a.contains(&json!("common.dot.dns.yandex.net")))
            }),
            "configured DoH hostname must be routed to dns-bootstrap"
        );
        let nx_rule = dns_rules
            .iter()
            .find(|r| r["rcode"] == "NXDOMAIN")
            .expect("effective_dns_intercept_all NXDOMAIN rule");
        let nx_suffixes = nx_rule["domain_suffix"].as_array().unwrap();
        assert!(
            !nx_suffixes.contains(&json!("dot.dns.yandex.net")),
            "configured DoH upstream suffix must not be self-blocked with NXDOMAIN"
        );

        // 2. Inverted AAAA suppression rule must isolate invert from query_type: ["AAAA"].
        let inv_cond = TrafficCondition {
            id: "inv_ru".to_string(),
            enabled: true,
            condition_type: "domain".to_string(),
            domains: vec!["ru".to_string()],
            invert: true,
            ..Default::default()
        };
        let mut cond_map = HashMap::new();
        cond_map.insert(inv_cond.id.as_str(), &inv_cond);
        let mut rule_sets = Vec::new();
        let mut seen = HashMap::new();
        let mut out = Vec::new();
        collect_condition_aaaa_dns_rules(
            &inv_cond,
            &cond_map,
            "/tmp",
            "",
            &mut rule_sets,
            &mut seen,
            false,
            false,
            0,
            &mut out,
        );
        assert_eq!(out.len(), 1);
        assert_eq!(out[0]["type"], "logical");
        assert_eq!(out[0]["mode"], "and");
        assert_eq!(out[0]["rcode"], "NOERROR");
        let and_rules = out[0]["rules"].as_array().unwrap();
        assert_eq!(and_rules[0], json!({ "query_type": ["AAAA"] }));
        assert_eq!(and_rules[1]["invert"], json!(true));
        assert!(and_rules[1].get("query_type").is_none());
    }

    #[test]
    fn test_section_dashboard_exclude_filters_propagate_to_default_urltest_balancer() {
        let mut store = RouterStoreData::default();
        store.settings.ipv6_mode = "off".to_string();
        let src = OutboundSource {
            id: "src_multi".to_string(),
            enabled: true,
            source_type: "proxy_links".to_string(),
            proxy_links: vec![
                "vless://11111111-1111-4111-8111-111111111111@good.example.com:443?security=none#GoodNode"
                    .to_string(),
                "vless://22222222-2222-4222-8222-222222222222@bad.example.com:443?security=none#BadNode"
                    .to_string(),
            ],
            ..Default::default()
        };
        store.outbound_sources.push(src);

        let sec = &mut store.sections[0];
        let sec_id = sec.id.clone();
        sec.enabled = true;
        sec.action = "connection".to_string();
        sec.connection_type = "proxy".to_string();
        sec.outbound_source_refs = vec!["src_multi".to_string()];
        sec.balancer_refs = vec!["bal_fastest".to_string()];
        sec.dashboard_filter_mode = "exclude".to_string();
        sec.dashboard_exclude_outbounds = vec!["BadNode".to_string()];

        let cfg = compile_core_config_with_wan6(&store, false).expect("compile cfg");
        let obs = cfg["outbounds"].as_array().unwrap();
        let bal_tag = format!("bal-{sec_id}-bal_fastest");
        let bal_ob = obs
            .iter()
            .find(|o| o["tag"] == bal_tag)
            .expect("urltest balancer outbound");
        let bal_members = bal_ob["outbounds"].as_array().unwrap();
        assert!(bal_members.contains(&json!("GoodNode")));
        assert!(!bal_members.contains(&json!("BadNode")));

        let sel_tag = format!("sel-{sec_id}");
        let sel_ob = obs
            .iter()
            .find(|o| o["tag"] == sel_tag)
            .expect("section selector outbound");
        let sel_members = sel_ob["outbounds"].as_array().unwrap();
        assert!(sel_members.contains(&json!("GoodNode")));
        assert!(!sel_members.contains(&json!("BadNode")));

        let caches = build_all_section_balancer_caches(&store);
        let (ug, _) = caches.get(&sec_id).expect("balancer cache for section");
        let ug_members = ug[&bal_tag]["outbounds"].as_array().unwrap();
        assert!(ug_members.contains(&json!("GoodNode")));
        assert!(!ug_members.contains(&json!("BadNode")));
    }

    #[test]
    fn test_all_subscription_formats_and_utf8_safety() {
        // 1. UTF-8 emoji in telemetry date segment must NEVER panic
        assert!(!matches_iso_or_eu_telemetry_date("(🌍-01-01)", false));
        assert!(!matches_iso_or_eu_telemetry_date("(01.01.🌍)", false));
        let cleaned = strip_dynamic_server_telemetry("Node (🌍-01-01) (01.01.🌍)");
        assert!(cleaned.contains("Node"));

        // 2. '+' preserved in wg/awg keys, query values, fragments, vmess#tag & boolean tls, hy2 mport
        let wg_uri = parse_proxy_uri(
            "awg://priv+Key/==@203.0.113.5:51820?publicKey=pub+Key/==&psk=pre+Key/==#AWG+Node",
            0,
        )
        .expect("awg uri with +");
        assert_eq!(wg_uri.tag, "AWG+Node");
        assert_eq!(wg_uri.outbound_json["private_key"], "priv+Key/==");
        assert_eq!(wg_uri.outbound_json["peer_public_key"], "pub+Key/==");
        assert_eq!(wg_uri.outbound_json["pre_shared_key"], "pre+Key/==");

        let vmess_b64 = B64_STD.encode(
            r#"{"v":"2","ps":"","add":"vm.example.com","port":"443","id":"11111111-1111-4111-8111-111111111111","net":"ws","tls":true,"host":"ws.example.com","path":"/v"}"#,
        );
        let vmess_frag = parse_proxy_uri(&format!("vmess://{vmess_b64}#VM%20Frag"), 0)
            .expect("vmess with fragment and bool tls");
        assert_eq!(vmess_frag.tag, "VM Frag");
        assert_eq!(vmess_frag.outbound_json["tls"]["enabled"], true);

        let vmess_uri = parse_proxy_uri(
            "vmess://11111111-1111-4111-8111-111111111111@vm2.example.com:443?security=tls&type=ws#VM-URI",
            1,
        )
        .expect("vmess uri syntax");
        assert_eq!(vmess_uri.server, "vm2.example.com");

        let hy2 = parse_proxy_uri(
            "hy2://pw+1@hy.example.com:443,1000-2000?mport=1000-2000&allowInsecure=1&alpn=h3#HY2",
            2,
        )
        .expect("hy2 port hopping");
        assert_eq!(hy2.server, "hy.example.com");
        assert_eq!(hy2.server_port, 443);
        assert_eq!(hy2.outbound_json["tls"]["insecure"], true);
        assert_eq!(hy2.outbound_json["server_ports"], json!(["1000:2000"]));

        let anytls = parse_proxy_uri("anytls://pw@any.example.com:443?insecure=1&alpn=h2#ANY", 3)
            .expect("anytls");
        assert_eq!(anytls.outbound_json["tls"]["insecure"], true);
        assert_eq!(anytls.outbound_json["tls"]["alpn"], json!(["h2"]));

        assert!(parse_proxy_uri("naive+https://u:p@n.example.com:443#N", 4).is_some());
        assert!(parse_proxy_uri("snell://psk123@s.example.com:4000?version=5#SN", 5).is_some());

        // 3. Multi-outbound Xray JSON without balancers keeps all nodes
        let multi_xray = json!({
            "outbounds": [
                {
                    "protocol": "vless",
                    "tag": "node-a",
                    "settings": { "vnext": [{ "address": "a.example.org", "port": 443, "users": [{ "id": "11111111-1111-4111-8111-111111111111" }] }] },
                    "streamSettings": { "security": "tls" }
                },
                {
                    "protocol": "trojan",
                    "tag": "node-b",
                    "settings": { "servers": [{ "address": "b.example.org", "port": 443, "password": "pw" }] }
                }
            ]
        })
        .to_string();
        let xray_nodes = parse_json_subscription_payload(&multi_xray).expect("multi xray");
        assert_eq!(xray_nodes.len(), 2);

        // 4. Outline single SS JSON, single outbound, URI array, panel wrapper, WG peers
        let outline_ss = r#"{"server":"198.51.100.10","server_port":8388,"method":"chacha20-ietf-poly1305","password":"pw","remarks":"Outline"}"#;
        assert_eq!(
            parse_json_subscription_payload(outline_ss).unwrap().len(),
            1
        );

        let uri_arr = json!(["vless://11111111-1111-4111-8111-111111111111@u1.example.com:443#U1"])
            .to_string();
        assert_eq!(parse_json_subscription_payload(&uri_arr).unwrap().len(), 1);

        let wrapped_panel = json!({
            "result": {
                "proxies": [{
                    "type": "wireguard",
                    "tag": "wg-ep",
                    "peers": [{ "address": "198.51.100.20", "port": 51820 }]
                }]
            }
        })
        .to_string();
        let wrapped_nodes = parse_json_subscription_payload(&wrapped_panel).unwrap();
        assert_eq!(wrapped_nodes.len(), 1);
        assert_eq!(wrapped_nodes[0].server, "198.51.100.20");
        assert_eq!(wrapped_nodes[0].server_port, 51820);

        // 5. Clash/Mihomo YAML: Proxy: (capital P), 4-space indent, trailing #comment on flow, anytls & awg
        let clash_yaml = concat!(
            "Proxy: # panel header\n",
            "  - {name: FlowNode, type: anytls, server: flow.example.com, port: 443, password: p1, skip-cert-verify: true} # inline comment\n",
            "  - name: FourSpaceWG\n",
            "      type: awg\n",
            "      server: wg.example.com\n",
            "      port: 51820\n",
            "      private-key: privK\n",
            "      public-key: pubK\n",
            "      jc: 3\n",
        );
        let yaml_nodes = parse_clash_yaml_subscription_payload(clash_yaml).expect("clash yaml");
        assert_eq!(yaml_nodes.len(), 2);
        assert_eq!(yaml_nodes[0].protocol, "anytls");
        assert_eq!(yaml_nodes[1].outbound_json["jc"], 3);

        // 6. Multi-server FPTN token extracts ALL servers
        let fptn_payload = json!({
            "username": "u1",
            "password": "p1",
            "servers": [
                { "name": "FI", "host": "fi.example.com", "port": 443 },
                { "name": "DE", "host": "de.example.com", "port": 443 }
            ]
        })
        .to_string();
        let fptn_tok = format!("fptn:{}", B64_STD.encode(fptn_payload.as_bytes()));
        assert_eq!(parse_fptn_token_nodes(&fptn_tok).len(), 2);
    }

    #[test]
